/bin/zsh -lc "cat > tb.sv <<'EOF'
module tb;
  reg clk=0, rst_n=0, data=0;
  wire match, not_match;
  TopModule dut(.clk(clk), .rst_n(rst_n), .data(data), .match(match), .not_match(not_match));
  always #5 clk=~clk;

  task send_bit(input reg b);
    begin
      data = b;
      #10;
      "'$display("t=%0t data=%0b p? match=%0b not_match=%0b", $time, b, match, not_match);
    end
  endtask

  initial begin
    #2; rst_n=0; data=0;
    #8; rst_n=1;
    // group1 fail immediately: 1xxxxx ; group2 also starts with 1 and should fail
    send_bit(1); send_bit(0); send_bit(0); send_bit(0); send_bit(0); send_bit(0);
    send_bit(1); send_bit(1); send_bit(1); send_bit(1); send_bit(1); send_bit(1);
    // group3 exact match should succeed
    send_bit(0); send_bit(1); send_bit(1); send_bit(1); send_bit(0); send_bit(0);
    #2; $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

