item.command:
/bin/zsh -lc "cat > tb_check.sv <<'EOF'
module tb;
  reg clk=0, rst_n=0, data=0;
  wire match, not_match;
  integer errors = 0;
  TopModule dut(.clk(clk), .rst_n(rst_n), .data(data), .match(match), .not_match(not_match));

  always #5 clk = ~clk;

  task send_bit(input reg b);
    begin
      data = b;
      #10;
    end
  endtask

  task expect_outputs(input reg exp_match, input reg exp_not_match, input [255:0] label);
    begin
      if (match "'!== exp_match || not_match !== exp_not_match) begin
        $display("FAIL %0s got match=%0b not_match=%0b expected %0b/%0b at t=%0t", label, match, not_match, exp_match, exp_not_match, $time);
        errors = errors + 1;
      end
    end
  endtask

  initial begin
    #2 rst_n = 0;
    #8 rst_n = 1;

    // Exact match: 011100
    send_bit(0); expect_outputs(0,0,"m1");
    send_bit(1); expect_outputs(0,0,"m2");
    send_bit(1); expect_outputs(0,0,"m3");
    send_bit(1); expect_outputs(0,0,"m4");
    send_bit(0); expect_outputs(0,0,"m5");
    send_bit(0); expect_outputs(1,0,"m6");

    // Immediate fail group: 100000
    send_bit(1); expect_outputs(0,0,"f1");
    send_bit(0); expect_outputs(0,0,"f2");
    send_bit(0); expect_outputs(0,0,"f3");
    send_bit(0); expect_outputs(0,0,"f4");
    send_bit(0); expect_outputs(0,0,"f5");
    send_bit(0); expect_outputs(0,1,"f6");

    // Boundary case: after a failed group, next group starts with 1 and must not be ignored
    // Actual group is 111100, so it must report not_match, never match.
    send_bit(1); expect_outputs(0,0,"b1");
    send_bit(1); expect_outputs(0,0,"b2");
    send_bit(1); expect_outputs(0,0,"b3");
    send_bit(1); expect_outputs(0,0,"b4");
    send_bit(0); expect_outputs(0,0,"b5");
    send_bit(0); expect_outputs(0,1,"b6");

    if (errors == 0) $display("PASS");
    else $display("FAILURES=%0d", errors);
    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv_check TopModule.sv tb_check.sv && vvp simv_check'

